class Solution {
    public ListNode detectCycle(ListNode head) {
        List<ListNode> visited = new ArrayList<>();
        for (ListNode curr = head; curr != null; curr = curr.next) {
            for (ListNode node : visited) {
                if (node == curr) return curr;   // first repeat = the entrance
            }
            visited.add(curr);
        }
        return null;
    }
}

