function detectCycle(head) {
  let slow = head;
  let fast = head;
  while (fast !== null && fast.next !== null) {
    slow = slow.next;
    fast = fast.next.next;
    if (slow === fast) {          // phase 1: there is a cycle
      let entry = head;
      while (entry !== slow) {    // phase 2: walk both one step at a time
        entry = entry.next;
        slow = slow.next;
      }
      return entry;               // they meet at the entrance
    }
  }
  return null;
}

class Solution {
    public ListNode detectCycle(ListNode head) {
        ListNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) {           // phase 1: there is a cycle
                ListNode entry = head;
                while (entry != slow) {   // phase 2: walk both one step at a time
                    entry = entry.next;
                    slow = slow.next;
                }
                return entry;             // they meet at the entrance
            }
        }
        return null;
    }
}

